-- # A column of a PRIMARY KEY is known not nullable, and a default is shown as
-- # it was written in the CREATE TABLE (6.20, Description, 7.c and 8). The
-- # columns for what vsql doesn't have (such as domains) are NULL.
CREATE TABLE foo (id INT PRIMARY KEY, name VARCHAR(20) DEFAULT 'it''s' NOT NULL);
SELECT * FROM information_schema.columns WHERE table_name = 'FOO';
