-- # The data type of each column. INTEGER types have a binary precision, and
-- # NUMERIC without a precision is 1000 (Part 2, 6.1, Syntax Rules, 20). FLOAT
-- # is stored as DOUBLE PRECISION. Each character is up to 4 octets (6.21,
-- # Description, 4.a). TIME is 0 and TIMESTAMP is 6 without a precision (Part
-- # 2, 6.1, Syntax Rules, 36).
CREATE TABLE t (a SMALLINT, b INTEGER, c BIGINT, d NUMERIC, e NUMERIC(10), f DECIMAL(10, 2), g REAL, h DOUBLE PRECISION, i FLOAT(10), j BOOLEAN, k CHAR, l CHARACTER(10), m VARCHAR(10485760), n DATE, o TIME, p TIME(3) WITH TIME ZONE, q TIMESTAMP, r TIMESTAMP(0) WITH TIME ZONE);
SELECT column_name, ordinal_position, data_type, character_maximum_length, character_octet_length, numeric_precision, numeric_precision_radix, numeric_scale, datetime_precision, character_set_catalog, character_set_schema, character_set_name, dtd_identifier FROM information_schema.columns WHERE table_name = 'T';
