-- # A CHECK that's exactly "c IS NOT NULL" means that the column can't be NULL,
-- # unless it's DEFERRABLE, and any other condition doesn't.
CREATE TABLE t (a INT CHECK (a IS NOT NULL), b INT NOT NULL, c INT, d INT, e INT, f INT, g INT, h INT, CHECK (c IS NOT NULL), CHECK (t.d IS NOT NULL), CHECK (e IS NOT NULL) DEFERRABLE, CHECK (f IS NOT NULL OR g IS NOT NULL), CHECK (h IS NULL));
SELECT column_name, is_nullable FROM information_schema.columns WHERE table_name = 'T';
-- msg: CREATE TABLE 1
-- COLUMN_NAME: A IS_NULLABLE: NO
-- COLUMN_NAME: B IS_NULLABLE: NO
-- COLUMN_NAME: C IS_NULLABLE: NO
-- COLUMN_NAME: D IS_NULLABLE: NO
-- COLUMN_NAME: E IS_NULLABLE: YES
-- COLUMN_NAME: F IS_NULLABLE: YES
-- COLUMN_NAME: G IS_NULLABLE: YES
-- COLUMN_NAME: H IS_NULLABLE: YES
